 64      fill(255, 255, 255, alphaVal);
 65      circle(s.x, s.y, s.size);
 66    }
 67  
 68    // Draw Sun glow and Sun
 69    push();
 70    translate(cx, cy);
 71    
 72    // Glow layers
 73    noStroke();
 74    for (let r = 50; r > 20; r -= 6) {
