 76      fill(255, 180, 50, alphaGlow);
 77      circle(0, 0, r * 2);
 78    }
 79    
 80    // Sun core
 81    let sunPulse = sin(frameCount * 0.05) * 1.5;
 82    fill(255, 220, 90);
 83    circle(0, 0, 42 + sunPulse);
 84    fill(255, 245, 180);
