101      let px = cos(p.angle) * p.dist;
102      let py = sin(p.angle) * p.dist;
103  
104      // Check hover
105      let dToMouse = dist(mRelX, mRelY, px, py);
106      let isHovered = dToMouse < p.radius + 6;
107      if (isHovered) {
