167      if (d > 10) {
168        force.normalize();
169        force.mult(120 / (d * 0.4 + 10));
170        ast.vel.add(force.mult(0.05 * timeSpeed));
171      }
172      
173      ast.pos.add(p5.Vector.mult(ast.vel, timeSpeed));
174      ast.life--;
175  
176      // Asteroid trail
177      ast.trail.push({ x: ast.pos.x, y: ast.pos.y });
178      if (ast.trail.length > 25) {
179        ast.trail.shift();
180      }
181  
182      // Draw trail
183      for (let t = 0; t < ast.trail.length - 1; t++) {
184        let trailAlpha = map(t, 0, ast.trail.length - 1, 10, 180);
185        stroke(ast.color.levels[0], ast.color.levels[1], ast.color.levels[2], trailAlpha);
186        strokeWeight(map(t, 0, ast.trail.length - 1, 1, 3));
