228  function mousePressed() {
229    dragStart = createVector(mouseX, mouseY);
230  }
231  
232  function mouseReleased() {
233    if (dragStart) {
234      let launchVec = createVector(dragStart.x - mouseX, dragStart.y - mouseY).mult(0.05);
235      let centerRelPos = createVector(dragStart.x - width / 2, dragStart.y - height / 2);
236      
237      asteroids.push({
238        pos: centerRelPos,
239        vel: launchVec,
240        size: random(3, 6),
241        color: color(random(180, 255), random(160, 220), random(200, 255)),
242        life: 600,
243        trail: []
244      });
245      dragStart = null;
246    }
247  }
